const ids = ["G01","G02","G03","G04","G05","G06"];
const results = await Promise.all(ids.map(id => tools.origin_packet({case_id: id})));
const out = [];
for (const r of results) {
  for (const c of r.cases) {
    const e = c.evidence;
    const src = new Map();
    for (const it of e.items) src.set(it.id, it.source_id);
    for (const mi of e.material_index) if (!src.has(mi.id)) src.set(mi.id, mi.source_id);
    const parents = new Map();
    for (const l of e.links) {
      if (l.relation !== "derivation") continue;
      if (!parents.has(l.child)) parents.set(l.child, []);
      parents.get(l.child).push(l.parent);
    }
    const memo = new Map();
    const origins = (id, stack = new Set()) => {
      if (memo.has(id)) return memo.get(id);
      const ps = (parents.get(id) || []);
      let s = new Set();
      if (ps.length === 0) s.add(src.get(id));
      else { for (const p of ps) for (const o of origins(p)) s.add(o); }
      memo.set(id, s);
      return s;
    };
    const all = new Set();
    for (const id of src.keys()) for (const o of origins(id)) all.add(o);
    const queries = c.query_ids.map(q => ({ material_id: q, origins: [...origins(q)].sort() }));
    out.push({ id: c.id, recorded_origin_count: all.size, independence: "unknown", queries });
  }
}
